-- Literal dialogue/hand-ins only; full-chain limitations: docs/coldain-quest-chains.md.
-- Ambient lecture timers and pupil signals are not yet converted. Chapel prayer belongs to the proximity listener, not the original targeted-NPC approximation.
local item_lib = require("items")

function event_trade(e)
  if item_lib.check_turn_in(e.trade, { item1 = 1418, item2 = 1428 }) then
    e.self:Say("My compliments, " .. e.other:GetCleanName() .. ", what a wonderful dish! Please accept my personal Seal as a token of my appreciation. May it give you power over your adversaries.")
    e.other:SummonItem(1422)
    e.other:AddEXP(200000)
    e.other:Faction(406, 10, 0)
    e.other:Faction(405, 10, 0)
    e.other:Faction(419, -30, 0)
    e.other:Faction(448, -30, 0)
  elseif item_lib.check_turn_in(e.trade, { item1 = 1428 }) then
    e.self:Say("My compliments, " .. e.other:GetCleanName() .. ", what a wonderful dish!")
    e.other:AddEXP(5000)
    e.other:Faction(406, 10, 0)
    e.other:Faction(405, 10, 0)
    e.other:Faction(419, -30, 0)
    e.other:Faction(448, -30, 0)
  end
  -- Return unrelated and surplus offers on both accepted and rejected trades.
  item_lib.return_items(e.self, e.other, e.trade)
end
